    @Override public boolean isItemValidForSlot(int i,ItemStack s){if(s==null)return false;if(kind==SpaceRegistry.ASSEMBLY)return i<11&&s.getItem()==SpaceRegistry.parts[i];if(kind==SpaceRegistry.COMPUTER)return i==0&&s.getItem()==SpaceRegistry.hdd;if(kind==SpaceRegistry.LAUNCH)return i==0&&s.getItem()==SpaceRegistry.rocket||i==1&&s.getItem()==SpaceRegistry.hdd;if(kind==SpaceRegistry.REFILL)return i==0&&ItemSpaceSuit.capacity(s)>0;if(i==2)return kind==SpaceRegistry.REFINERY&&s.getItem()==Items.coal||kind==SpaceRegistry.COMPRESSOR&&s.getItem()==SpaceRegistry.airFilter;return i==0&&s.getItem() instanceof IFluidContainerItem;}
