    public NBTTagCompound snapshot(){NBTTagCompound n=new NBTTagCompound();n.setInteger("Kind",kind);n.setBoolean("Shuttle",ShuttleVehicle.is(this));n.setInteger("Energy",energy);n.setInteger("Progress",progress);n.setInteger("Target",target);n.setBoolean("Enabled",enabled);n.setBoolean("Reserve",returnReserve);n.setString("Status",status);n.setInteger("Pressure",pressure);n.setBoolean("Sealed",sealed);n.setInteger("Volume",roomVolume);n.setString("Room",roomMessage);n.setInteger("LockPressure",lockPressure);n.setInteger("LockCycle",lockCycle);n.setString("Lock",lockStatus);if(kind==SpaceRegistry.AIRLOCK)Airlock.snapshot(this,n);for(int i=0;i<3;i++){NBTTagCompound f=new NBTTagCompound();tanks[i].writeToNBT(f);n.setTag("Tank"+i,f);}return n;}
    @Override public void writeToNBT(NBTTagCompound n){super.writeToNBT(n);NBTTagCompound s=snapshot();for(Object key:s.func_150296_c())n.setTag((String)key,s.getTag((String)key));n.setInteger("SpaceMachineVersion",1);n.setString("Owner",owner);n.setInteger("RoomGas",gas);n.setBoolean("Landed",landed);n.setTag("Vehicle",vehicle.copy());NBTTagList list=new NBTTagList();for(int i=0;i<12;i++)if(items[i]!=null){NBTTagCompound tag=new NBTTagCompound();tag.setByte("Slot",(byte)i);items[i].writeToNBT(tag);list.appendTag(tag);}n.setTag("Inventory",list);}
    @Override public void readFromNBT(NBTTagCompound n){super.readFromNBT(n);kind=Math.max(0,Math.min(10,n.getInteger("Kind")));energy=Math.max(0,Math.min(1000000,n.getInteger("Energy")));progress=Math.max(0,Math.min(100,n.getInteger("Progress")));target=Math.max(0,Math.min(2,n.getInteger("Target")));enabled=!n.hasKey("Enabled")||n.getBoolean("Enabled");returnReserve=!n.hasKey("Reserve")||n.getBoolean("Reserve");owner=n.getString("Owner");gas=Math.max(0,Math.min(SpaceConfig.maxRoom*SpaceConfig.airPerBlock,n.getInteger("RoomGas")));lockPressure=Math.max(0,Math.min(100,n.getInteger("LockPressure")));lockCycle=Math.max(0,Math.min(2,n.getInteger("LockCycle")));roomVolume=Math.max(0,Math.min(SpaceConfig.maxRoom,n.getInteger("Volume")));landed=n.getBoolean("Landed");vehicle=n.getCompoundTag("Vehicle");for(int i=0;i<3;i++)tanks[i].readFromNBT(n.getCompoundTag("Tank"+i));items=new ItemStack[12];NBTTagList list=n.getTagList("Inventory",10);for(int i=0;i<Math.min(12,list.tagCount());i++){NBTTagCompound v=list.getCompoundTagAt(i);int slot=v.getByte("Slot")&255;if(slot<12)items[slot]=ItemStack.loadItemStackFromNBT(v);}sealed=false;room=Collections.emptySet();lastScan=-1000;scan=null;}
    @Override public Packet getDescriptionPacket(){NBTTagCompound n=new NBTTagCompound();n.setInteger("Kind",kind);n.setBoolean("Shuttle",ShuttleVehicle.is(this));n.setBoolean("Rocket",kind==SpaceRegistry.LAUNCH&&items[0]!=null);return new S35PacketUpdateTileEntity(xCoord,yCoord,zCoord,1,n);}
